const HEADER_SERVICES_I18N={"fr":["HEAD SPA","MODELAGE","MASSAGE","RÉFLEXOLOGIE","NATUROPATHIE"],"en":["HEAD SPA","BODY TREATMENTS","MASSAGE","REFLEXOLOGY","NATUROPATHY"],"es":["HEAD SPA","TRATAMIENTOS","MASAJES","REFLEXOLOGÍA","NATUROPATÍA"],"de":["HEAD SPA","KÖRPERPFLEGE","MASSAGE","REFLEXOLOGIE","NATURHEILKUNDE"],"it":["HEAD SPA","TRATTAMENTI","MASSAGGI","RIFLESSOLOGIA","NATUROPATIA"],"nl":["HEAD SPA","LICHAAMSZORG","MASSAGE","REFLEXOLOGIE","NATUROPATHIE"],"ru":["СПА ДЛЯ ГОЛОВЫ","УХОД ЗА ТЕЛОМ","МАССАЖ","РЕФЛЕКСОЛОГИЯ","НАТУРОПАТИЯ"],"zh":["头皮水疗","身体护理","按摩","反射疗法","自然疗法"],"ja":["ヘッドスパ","ボディケア","マッサージ","リフレクソロジー","ナチュロパシー"]};
const companyStack={"fr":["Massages","en entreprise"],"en":["Workplace","massage"],"es":["Masajes","en empresas"],"de":["Massage","im Unternehmen"],"it":["Massaggi","in azienda"],"nl":["Massage","op het werk"],"ru":["Массаж","в компании"],"zh":["企业","按摩"],"ja":["法人向け","マッサージ"]};function menuStack(route,label){const parts=route==='entreprises'?companyStack[lang]:lang==='fr'?(route==='bien-etre-a-deux'?['Bien-être','à deux']:route==='cartes-cadeaux'?['Cartes','cadeaux']:route==='contact-et-acces'?['Contact','et accès']:null):null;return parts?parts.join('<br>'):label;}
function nav(){const t=LANG[lang];const headerTreatments=document.querySelector('.header-treatments');const services=HEADER_SERVICES_I18N[lang]||HEADER_SERVICES_I18N.fr;headerTreatments.querySelectorAll('span').forEach((el,i)=>{el.textContent=services[i]});headerTreatments.setAttribute('aria-label',services.join(', '));let labels=[['',t.home],['soins',t.treatments],['bien-etre-a-deux',DUO_I18N[lang][0]],['le-lieu',t.place],['galerie',t.gallery],['cartes-cadeaux',lang==='fr'?'Cartes cadeaux':t.gifts],['entreprises',COMPANY_NAV[lang]||COMPANY_NAV.fr],['contact-et-acces',t.contact]];document.getElementById('links').innerHTML=labels.map(([r,l])=>`<a href="${link(r)}">${menuStack(r,l)}</a>`).join('')+`<a href="${PLANITY}" target="_blank" rel="noopener">${t.book}</a>`;document.getElementById('footer-nav').innerHTML=labels.map(([r,l])=>`<a href="${link(r)}">${l}</a>`).join('')+`<a href="https://search.google.com/local/writereview?placeid=ChIJgcMCKWzN4UcRj8HBP2_rgvI" target="_blank" rel="noopener">${REVIEW_LABELS[lang][1]}</a><a href="/#/mentions-legales">${LEGAL_TRANSLATIONS[lang]?.legal||"Mentions légales"}</a><a href="/#/politique-confidentialite">${LEGAL_TRANSLATIONS[lang]?.privacy||"Politique de confidentialité"}</a><a href="/#/cookies">${LEGAL_TRANSLATIONS[lang]?.cookies||"Cookies"}</a>`;document.getElementById('seo-service-links').innerHTML=SERVICES.map((v,i)=>`<a href="${v.id}">${t.serviceNames[i]}</a>`).join('');document.getElementById('footer-note').textContent=t.illustration;document.getElementById('language').value=lang;document.documentElement.lang=lang;}
function card(s,i){const t=LANG[lang];s={...s,...serviceCopy(s,i)};return `<a class="card" href="${lang==='fr'?`/${s.id}`:link(s.id)}">${img(s.image,'Illustration : '+s.name)}<div class="body"><span class="eyebrow">0${i+1} · LE COCON</span><h3>${t.serviceNames[i]}</h3><p>${s.teaser}</p><span class="more">${t.more}</span></div></a>`}
function hero(title,text,image,eyebrow,ctaRoute='',ctaText=''){const t=LANG[lang];return `<section class="hero"><div class="copy"><span class="eyebrow">${eyebrow||t.kicker}</span><h1>${title}</h1><p class="lead">${text}</p><div class="actions"><a class="btn" href="${PLANITY}" target="_blank" rel="noopener">${t.book}</a>${ctaText?`<a class="btn btn-ghost" href="${link(ctaRoute)}">${ctaText}</a>`:''}</div></div><div class="hero-img">${img(image,'Illustration du soin')}</div></section>`}
const CHRISTMAS_GIFT_LABELS={"fr":"Offrir une carte cadeau pour Noël","en":"Give a Christmas gift card","es":"Regalar una tarjeta regalo por Navidad","de":"Weihnachtsgutschein verschenken","it":"Regala una carta regalo per Natale","nl":"Geef een kerstcadeaubon","ru":"Подарить подарочную карту на Рождество","zh":"赠送圣诞礼品卡","ja":"クリスマスギフトカードを贈る"};
const GIFT_EVERGREEN_LABELS={fr:"Offrir une carte cadeau",en:"Give a gift card",es:"Regalar una tarjeta regalo",de:"Einen Gutschein verschenken",it:"Regala una carta regalo",nl:"Geef een cadeaubon",ru:"Подарить подарочную карту",zh:"赠送礼品卡",ja:"ギフトカードを贈る"};
function coconFestiveActive(){const d=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const v=Object.fromEntries(d.map(p=>[p.type,p.value]));const date=v.year+'-'+v.month+'-'+v.day;return date>='2026-11-27'&&date<'2027-01-05'}
function coconFestiveDecor(){if(!coconFestiveActive())return '';let branches='';for(let i=0;i<64;i++){let x=i*20-20,y=12+17*Math.sin(i*.24);for(let side of [-1,1]){let dx=side*(38+i%4*5),dy=36+i%5*4;branches+='<path d="M'+x+' '+y+' l'+dx+' '+dy+'" stroke="#244c35" stroke-width="5"/>';for(let j=1;j<=9;j++){let f=j/10,px=x+dx*f,py=y+dy*f;for(let k of [-1,1])branches+='<path d="M'+px+' '+py+' l'+(side*12+k*11)+' '+(k===1?17:-9)+'" stroke="'+['#315c3c','#47754b','#1b392b','#688653'][(i+j+(k+1))%4]+'" stroke-width="2" stroke-linecap="round"/>'}}}const greenery='<svg class="cocon-festive-greenery" viewBox="0 0 1200 90" preserveAspectRatio="none" aria-hidden="true"><path d="M0 8 Q300 38 600 12 T1200 8" fill="none" stroke="#23432e" stroke-width="19"/>'+branches+'</svg>';const bulbs=Array.from({length:65},(_,i)=>'<i class="cocon-festive-bulb" style="--x:'+(1+i*98/64)+'%;--y:'+(30+17*Math.sin(i*.66))+'px;--delay:-'+(i%9)*.29+'s"></i>').join('');const drops=[3,9,17,30,50,70,83,91,97].map((x,i)=>'<i class="cocon-festive-drop" style="--x:'+x+'%;--h:'+(39+(i%3)*15)+'px;--delay:-'+i*.43+'s"></i>').join('');const balls=Array.from({length:24},(_,i)=>'<i class="cocon-festive-bauble '+(i%3===0?'red':'')+'" style="--x:'+(2+i*95/23)+'%;--y:'+(20+i%3*10)+'px"></i>').join('');return '<div class="cocon-festive" aria-hidden="true">'+greenery+balls+bulbs+drops+Array.from({length:32},(_,i)=>'<i class="cocon-festive-spark" style="--x:'+((i*37+3)%98)+'%;--y:'+(9+(i*17)%49)+'px;--delay:-'+(i%11)*.37+'s">✦</i>').join('')+'<div class="cocon-festive-greeting">'+(FESTIVE_GREETING[lang]||FESTIVE_GREETING.fr)+'</div></div>'}
const FESTIVE_GREETING={fr:"Bonnes fêtes de fin d’année !",en:"Happy holidays!",es:"¡Felices fiestas!",de:"Frohe Festtage!",it:"Buone feste!",nl:"Fijne feestdagen!",ru:"С наступающими праздниками!",zh:"节日快乐！",ja:"素敵な年末年始を！"};
function homeHero(){const t=LANG[lang];return `<section class="hero-home with-storefront ${coconFestiveActive()?'cocon-seasonal':''}" style="--storefront:url('${CUSTOM_MEDIA.vitrine}')">${coconFestiveDecor()}<div class="copy"><div class="hero-logo-lockup">${img('logo-le-cocon','Logo Le Cocon Bien-être')}</div><span class="eyebrow home-services"><span>${(HEADER_SERVICES_I18N[lang]||HEADER_SERVICES_I18N.fr).join(" · ")}</span></span><h1>${t.title.replace('attendre.','<em>attendre.</em>')}</h1><p class="lead">${t.hero}</p><div class="actions"><a class="btn" href="${PLANITY}" target="_blank" rel="noopener">${t.book}</a><a class="btn btn-ghost" href="${link('soins')}">${t.discover}</a><a class="btn btn-ghost christmas-gift-cta" href="${link('cartes-cadeaux')}"><span class="christmas-stars christmas-stars-left" aria-hidden="true"><i></i><i></i><i></i><i></i><i class="desktop-extra-star"></i><i class="desktop-extra-star"></i><i class="desktop-extra-star"></i><i class="desktop-more-star"></i><i class="desktop-more-star"></i><i class="desktop-more-star"></i><i class="desktop-more-star"></i></span><span class="christmas-gift-label">${(coconFestiveActive()?CHRISTMAS_GIFT_LABELS:GIFT_EVERGREEN_LABELS)[lang]||t.gifts}</span><span class="christmas-stars christmas-stars-right" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i class="desktop-extra-star"></i><i class="desktop-extra-star"></i><i class="desktop-extra-star"></i><i class="desktop-more-star"></i><i class="desktop-more-star"></i><i class="desktop-more-star"></i><i class="desktop-more-star"></i></span></a></div></div></section>`}
function cta(extraClass=""){const t=LANG[lang];return `<section class="cta ${extraClass}"><div class="eyebrow">LE COCON · PONT-L’ÉVÊQUE</div><h2>${t.title}</h2><p>${t.hero}</p><a class="btn" href="${PLANITY}" target="_blank" rel="noopener">${t.book}</a></section>`}
