function reviews(){const [title,description,button]=REVIEW_I18N[lang]||REVIEW_I18N.fr;return `<section class="review-feature"><div class="review-feature-inner"><div class="review-feature-copy"><span class="eyebrow">${REVIEW_LABELS[lang][0]} · LE COCON</span><h2>${title}</h2><p>${description}</p></div><a class="review-feature-button" href="https://search.google.com/local/writereview?placeid=ChIJgcMCKWzN4UcRj8HBP2_rgvI" target="_blank" rel="noopener noreferrer"><span class="review-google-mark">G</span><span>${button} </span></a></div></section>`}
