function homepageTestimonials(){const copy=TESTIMONIAL_COPY[lang]||TESTIMONIAL_COPY.fr;return `<section class="testimonials"><div class="testimonials-inner"><div class="testimonials-heading"><span class="eyebrow">LE COCON · GOOGLE &amp; PLANITY</span><h2>${copy[0]}</h2><p>${copy[1]}</p></div><div class="testimonial-grid">${FEATURED_REVIEWS.map(review=>`<article class="testimonial-card"><span class="testimonial-stars" aria-label="5 étoiles sur 5">★★★★★</span><blockquote>« ${review.quote} »</blockquote><p class="testimonial-source">Avis ${review.source}</p></article>`).join('')}</div></div></section>${reviews()}`}
const COMPANY_NAV={"fr":"Entreprises","en":"Businesses","es":"Empresas","de":"Unternehmen","it":"Aziende","nl":"Bedrijven","ru":"Компаниям","zh":"企业服务","ja":"法人向け"};
const COMPANY_MASSAGE_I18N={"fr":["Massages en entreprise","Offrez une pause bien-être à vos collaboratrices","Le Cocon se déplace directement dans vos locaux avec sa table de massage et tout le matériel nécessaire pour proposer des massages bien-être à vos collaboratrices.","Les interventions peuvent être organisées sur une ou plusieurs journées, selon le nombre de collaboratrices et les besoins de votre entreprise.","Nous contacter"],"en":["Workplace massage","Give your female employees a moment of relaxation","Le Cocon comes to your workplace with a massage table and all the equipment needed to offer relaxing massages to your female employees.","Visits can be arranged over one or more days, depending on the number of female participants and needs.","Contact us"],"es":["Masajes en empresas","Ofrece una pausa de bienestar a tus colaboradoras","Le Cocon se desplaza a tus instalaciones con camilla y todo el material necesario para ofrecer masajes de bienestar a tus colaboradoras.","Las sesiones pueden organizarse durante uno o varios días, según el número de participantes y las necesidades de tu empresa.","Contáctanos"],"de":["Massagen im Unternehmen","Gönnen Sie Ihren Mitarbeiterinnen eine entspannende Auszeit","Le Cocon kommt mit Massageliege und der gesamten benötigten Ausstattung direkt in Ihr Unternehmen.","Die Einsätze können je nach Anzahl der Teilnehmerinnen und Bedarf an einem oder mehreren Tagen stattfinden.","Kontakt aufnehmen"],"it":["Massaggi in azienda","Offri una pausa di benessere alle tue collaboratrici","Le Cocon viene direttamente nella tua azienda con lettino e tutto il materiale necessario per offrire massaggi rilassanti alle tue collaboratrici.","Gli interventi possono svolgersi in una o più giornate, in base al numero di partecipanti e alle esigenze aziendali.","Contattaci"],"nl":["Massages op het werk","Geef uw vrouwelijke medewerkers een ontspannen pauze","Le Cocon komt naar uw bedrijf met een massagetafel en alle benodigdheden voor ontspannende massages.","De bezoeken kunnen één of meerdere dagen duren, afhankelijk van de het aantal deelneemsters en uw wensen.","Neem contact op"],"ru":["Массаж в офисе","Подарите сотрудницам время для отдыха","Le Cocon приезжает в вашу компанию с массажным столом и всем необходимым оборудованием для расслабляющего массажа.","Выезды можно организовать на один или несколько дней с учетом числа сотрудниц и потребностей компании.","Связаться с нами"],"zh":["企业按摩服务","为女性员工提供放松身心的休息时光","Le Cocon 携带按摩床及所需设备，直接到您的企业为女性员工提供放松按摩。","可根据女性员工人数和企业需求安排一天或多天的服务。","联系我们"],"ja":["企業向け出張マッサージ","女性従業員の皆さまにリラックスできるひとときを","Le Coconはマッサージベッドと必要な備品を持参し、職場でリラクゼーションマッサージを提供します。","女性従業員数や企業のご希望に応じて、1日または複数日の訪問が可能です。","お問い合わせ"]};
const COMPANY_PRIVACY={"fr":"Afin de préserver l’intimité et le confort de chacune, les massages en entreprise sont exclusivement réservés aux femmes.","en":"To preserve each participant’s privacy and comfort, workplace massages are exclusively reserved for women.","es":"Para preservar la intimidad y la comodidad de cada participante, los masajes en empresas están reservados exclusivamente a mujeres.","de":"Um die Privatsphäre und das Wohlbefinden jeder Teilnehmerin zu wahren, sind Massagen im Unternehmen ausschließlich Frauen vorbehalten.","it":"Per tutelare la riservatezza e il comfort di ciascuna partecipante, i massaggi in azienda sono riservati esclusivamente alle donne.","nl":"Om de privacy en het comfort van iedere deelneemster te waarborgen, zijn massages op het werk uitsluitend voor vrouwen.","ru":"Для сохранения приватности и комфорта каждой участницы массаж в компаниях предназначен исключительно для женщин.","zh":"为保护每位参与者的隐私和舒适感，企业按摩服务仅面向女性。","ja":"お一人おひとりのプライバシーと快適さを大切にするため、企業向けマッサージは女性限定です。"};
function companyPage(){const c=COMPANY_MASSAGE_I18N[lang]||COMPANY_MASSAGE_I18N.fr;return `<section class="split"><div class="copy"><span class="eyebrow">LE COCON</span><h1>${c[0]}</h1><h2>${c[1]}</h2><p>${c[2]}</p><p>${COMPANY_PRIVACY[lang]||COMPANY_PRIVACY.fr}</p><a class="btn" href="mailto:salon@lecocon14.com">${c[4]}</a></div>${img("massage-bien-etre",LANG[lang].illustration)}</section><section class="split">${img("reflexologie-palmaire",LANG[lang].illustration)}<div class="copy"><h2>${c[0]}</h2><p>${c[3]}</p><a class="btn" href="${link("contact-et-acces")}">${c[4]}</a></div></section><div class="note">${LANG[lang].illustration}</div>`}
function companyMassage(){const c=COMPANY_MASSAGE_I18N[lang]||COMPANY_MASSAGE_I18N.fr;return `<section class="section" id="massages-entreprise"><div class="container"><div class="sectiontop"><span class="eyebrow">${c[0]}</span><h2>${c[1]}</h2><p>${c[2]}</p><p>${COMPANY_PRIVACY[lang]||COMPANY_PRIVACY.fr}</p><p>${c[3]}</p><div class="actions" style="justify-content:center;margin-top:24px"><a class="btn" href="${link('contact-et-acces')}">${c[4]}</a></div></div></div></section>`}
const DUO_I18N={"fr":["Bien-être à deux","Duo bien-être, chacun son moment","Partagez une parenthèse de détente avec la personne de votre choix.","Pearl exerce seule au Cocon et réalise personnellement chaque soin. Vos soins se déroulent l’un après l’autre, et non simultanément, afin que chacun bénéficie de toute son attention.","Pendant le soin de l’autre, vous pouvez, si vous le souhaitez, vous installer confortablement dans notre espace détente. Un café, un thé ou une infusion vous sont proposés gracieusement. Prenez le temps de lire, de vous relaxer ou de profiter du Wi-Fi mis à votre disposition.","Organiser vos deux soins successifs","Offrez une parenthèse de bien-être à deux","Découvrir l’expérience à deux"],"en":["Wellness for two","Wellness for two, a moment of your own","Share a relaxing break with someone of your choice.","Pearl works alone at Le Cocon and personally provides every treatment. Treatments take place one after the other, not simultaneously, so each guest receives her full attention.","While the other guest enjoys their treatment, you are welcome to relax in our lounge with a complimentary coffee, tea or herbal infusion. Read, unwind or use the available Wi-Fi.","Arrange your two consecutive treatments","Give the gift of wellness for two","Discover wellness for two"],"es":["Bienestar para dos","Bienestar para dos, un momento para cada persona","Comparta una pausa de relajación con quien desee.","Pearl trabaja sola en Le Cocon y realiza personalmente cada tratamiento. Los tratamientos se realizan uno después del otro, no simultáneamente, para dedicar toda su atención a cada persona.","Mientras la otra persona disfruta de su tratamiento, puede descansar en nuestra zona de relajación con un café, té o infusión de cortesía. Puede leer, relajarse o utilizar el Wi-Fi disponible.","Organizar sus dos tratamientos consecutivos","Regale una pausa de bienestar para dos","Descubrir el bienestar para dos"],"de":["Wellness zu zweit","Wellness zu zweit, Zeit für jeden","Genießen Sie eine entspannende Auszeit mit einer Person Ihrer Wahl.","Pearl arbeitet allein im Le Cocon und führt jede Behandlung persönlich durch. Die Behandlungen finden nacheinander statt, nicht gleichzeitig, damit jede Person ihre volle Aufmerksamkeit erhält.","Während der Behandlung der anderen Person können Sie sich in unserem Ruhebereich bei einem kostenlosen Kaffee, Tee oder Kräutertee entspannen, lesen oder das WLAN nutzen.","Zwei aufeinanderfolgende Behandlungen vereinbaren","Verschenken Sie Wellness zu zweit","Wellness zu zweit entdecken"],"it":["Benessere in due","Benessere in due, un momento per ciascuno","Condividete una pausa di relax con chi desiderate.","Pearl lavora da sola al Cocon ed esegue personalmente ogni trattamento. I trattamenti si svolgono uno dopo l’altro, non contemporaneamente, per dedicare a ciascuno tutta la sua attenzione.","Durante il trattamento dell’altra persona, potete accomodarvi nella zona relax con un caffè, un tè o una tisana offerti. Potete leggere, rilassarvi o utilizzare il Wi-Fi disponibile.","Prenotare due trattamenti consecutivi","Regalate una pausa di benessere in due","Scoprire il benessere in due"],"nl":["Wellness voor twee","Wellness voor twee, ieder een eigen moment","Deel een ontspannen moment met iemand naar keuze.","Pearl werkt alleen bij Le Cocon en verzorgt elke behandeling persoonlijk. De behandelingen vinden na elkaar plaats, niet tegelijkertijd, zodat iedereen haar volledige aandacht krijgt.","Tijdens de behandeling van de ander kunt u ontspannen in onze zithoek met gratis koffie, thee of kruidenthee. Lees, rust uit of gebruik de beschikbare wifi.","Plan uw twee opeenvolgende behandelingen","Geef wellness voor twee cadeau","Ontdek wellness voor twee"],"ru":["Отдых для двоих","Отдых для двоих, время для каждого","Разделите минуты отдыха с близким человеком.","Перл работает в Le Cocon одна и лично проводит все процедуры. Процедуры проходят по очереди, а не одновременно, чтобы каждый гость получил её полное внимание.","Пока другой гость наслаждается процедурой, вы можете отдохнуть в уютной зоне отдыха. Мы предлагаем бесплатный кофе, чай или травяной настой. Можно почитать, расслабиться или воспользоваться Wi-Fi.","Организовать две процедуры по очереди","Подарите отдых для двоих","Узнать об отдыхе для двоих"],"zh":["双人放松体验","双人放松，各享专属时光","与您选择的伙伴共享一段放松时光。","Pearl 独自在 Le Cocon 工作，亲自提供每项护理。两人的护理依次进行，而非同时进行，让每位顾客都能获得她的悉心照顾。","另一位享受护理时，您可以在舒适的休息区放松，享用免费咖啡、茶或花草茶，也可以阅读、休息或使用 Wi-Fi。","安排两人依次护理","赠送双人放松体验","了解双人体验"],"ja":["お二人での癒やし","お二人で、ひとりずつの癒やし時間","大切な方とリラックスしたひとときをお過ごしください。","Le Cocon では Pearl が一人で営業し、すべての施術を担当します。お一人ずつ順番に施術を行い、同時施術は行いません。お一人おひとりに丁寧に対応します。","お連れ様の施術中は、休憩スペースで無料のコーヒー、紅茶、ハーブティーをお楽しみいただけます。読書や休息、Wi-Fi のご利用も可能です。","お二人の順番施術を相談する","お二人に癒やしの時間を贈る","お二人での体験を見る"]};
function duoFeature(gift=false){const c=DUO_I18N[lang]||DUO_I18N.fr;return `<section class="section"><div class="container"><div class="info-card" style="text-align:center;padding:clamp(22px,5vw,48px);max-width:900px;margin:auto"><span class="eyebrow">LE COCON · ${c[0]}</span><h2>${gift?c[6]:c[1]}</h2><p>${c[2]}</p><p>${c[3]}</p><a class="btn btn-ghost" href="/bien-etre-a-deux">${c[7]}</a></div></div></section>`}
function duoPage(){const c=DUO_I18N[lang]||DUO_I18N.fr,t=LANG[lang];return `<section class="hero"><div class="copy"><span class="eyebrow">LE COCON · ${c[0]}</span><h1>${c[1]}</h1><p class="lead">${c[2]}</p><p>${c[3]}</p><div class="actions"><a class="btn" href="/contact-et-acces">${c[5]}</a></div></div><div class="hero-img"><img src="${CUSTOM_MEDIA.lieu}" alt="${t.place} · Le Cocon"></div></section><section class="split">${img('massage-huiles',t.illustration)}<div class="copy"><span class="eyebrow">LE COCON</span><h2>${c[0]}</h2><p>${c[4]}</p><p>${MASSAGE_PRIVACY[lang]}</p><div class="actions"><a class="btn" style="background:#384144;color:#fff;border-color:#384144" href="/galerie">${t.gallery}</a><a class="btn" style="background:#384144;color:#fff;border-color:#384144" href="/cartes-cadeaux">${lang==='fr'?'Cartes cadeaux':t.gifts}</a></div></div></section>${salonGallery()}`}
function home(){const t=LANG[lang],e=EXTRA_I18N[lang]||EXTRA_I18N.fr;return `${homeHero()}<div class="band"><span>✧ Head Spa</span><span>${e[0]}</span><span>${e[1]}</span></div><section class="section"><div class="container"><div class="sectiontop"><span class="eyebrow">${e[2]}</span><h2>${t.rituals}</h2><p>${t.intro}</p><p>${MASSAGE_PRIVACY[lang]}</p></div><div class="grid">${SERVICES.slice(0,6).map(card).join('')}</div><div class="actions" style="justify-content:center;margin-top:38px"><a class="btn btn-ghost" href="/soins">${t.all}</a></div></div></section>${homepageTestimonials()}<section class="split">${img('reflexologie-palmaire','Illustration de réflexologie')}<div class="copy"><span class="eyebrow">LE COCON</span><h2>${t.experience}</h2><p>${t.experienceBody}</p><a class="btn" href="/le-lieu">${t.ourWorld}</a></div></section>${salonGallery()}${cta()}`}
function list(){const t=LANG[lang];return `<section class="section"><div class="container"><div class="sectiontop"><span class="eyebrow">LE COCON</span><h1>${t.treatments}</h1><p>${t.intro}</p></div><div class="grid">${SERVICES.map(card).join('')}</div></div></section>${duoFeature()}${cta()}`}
const MASSAGE_PRIVACY={"fr":"Les massages au Cocon s’adressent principalement à une clientèle féminine. Dans le cadre d’une parenthèse bien-être en couple, Pearl accueille également les hommes accompagnés de leur compagne, pour partager ensemble cette expérience de détente.","en":"Massage treatments at Le Cocon are primarily intended for women. Pearl also welcomes men accompanied by their female partner as part of a couples’ wellness experience.","es":"Los masajes en Le Cocon se destinan principalmente a una clientela femenina. Pearl también recibe a hombres acompañados de su pareja femenina para disfrutar de una experiencia de bienestar en pareja.","de":"Die Massagen im Le Cocon richten sich hauptsächlich an Frauen. Im Rahmen einer Wellness-Auszeit für Paare empfängt Pearl auch Männer in Begleitung ihrer Partnerin.","it":"I massaggi al Cocon sono rivolti principalmente a una clientela femminile. Pearl accoglie anche gli uomini accompagnati dalla propria compagna per un’esperienza di benessere in coppia.","nl":"De massages bij Le Cocon zijn voornamelijk bedoeld voor vrouwen. Pearl verwelkomt ook mannen die samen met hun vrouwelijke partner komen voor een wellnessmoment als koppel.","ru":"Массаж в Le Cocon предназначен преимущественно для женщин. Перл также принимает мужчин в сопровождении их партнёрши в рамках совместного отдыха для пары.","zh":"Le Cocon 的按摩服务主要面向女性。情侣双人放松体验中，Pearl 也欢迎由女性伴侣陪同前来的男士。","ja":"Le Cocon のマッサージは主に女性のお客様を対象としています。カップルでの癒やし体験では、女性のパートナーとご来店される男性も Pearl がお迎えします。"};
function details(s){const t=LANG[lang],i=SERVICES.findIndex(x=>x.id===s.id);s={...s,...serviceCopy(s,i)};return `${hero(t.serviceNames[i],s.subtitle,s.image,t.kicker,'soins',t.back)}<div class="note">${t.illustration}</div><section class="section"><div class="container"><div class="sectiontop"><span class="eyebrow">${t.details}</span><h2>${s.subtitle}</h2><p>${s.detail}</p>${s.id.startsWith('massage-')?'<p>'+MASSAGE_PRIVACY[lang]+'</p>':''}</div><div class="info-cards"><div class="info-card"><h3>${t.experience}</h3><p>${s.teaser}</p></div><div class="info-card"><h3>${t.practical}</h3><p>12 rue Ménars, 14130 Pont-l’Évêque</p>${lang==='fr'?'<p>Vous venez de Deauville, Trouville-sur-Mer, Honfleur, Lisieux, Beuzeville, Cabourg ou Ouistreham ? <a href="/contact-et-acces">Préparez votre trajet jusqu’au salon.</a></p>':''}</div><div class="info-card"><h3>Planity</h3><p>${AUDIT_COPY[lang][3]}</p><a class="btn" href="${PLANITY}" target="_blank" rel="noopener">${t.book}</a></div></div><div class="mini-links"><a href="/soins">← ${t.back}</a><a href="/cartes-cadeaux">${t.tryGift}</a></div></div></section>`}

const SERVICE_I18N={"en":[["A soothing ritual for the scalp","Enjoy a gentle scalp and hair treatment designed to help you unwind."],["The art of relaxation","Gentle, flowing movements invite you to release everyday tension."],["Comforting warmth","Warm stones and slow movements create a deeply relaxing experience."],["A sensory escape","Soft oil massage movements offer a peaceful moment just for you."],["Relaxation focused on the feet","Gentle, targeted pressure on the feet for a calming break."],["A moment of care for your hands","A delicate hand-focused treatment in a soothing atmosphere."],["A holistic well-being consultation","Personalised guidance to explore your everyday well-being habits."]],"es":[["Un ritual relajante para el cuero cabelludo","Disfruta de un cuidado suave del cuero cabelludo y del cabello para desconectar."],["El arte de relajarse","Los movimientos suaves y envolventes ayudan a liberar las tensiones cotidianas."],["Calor reconfortante","Las piedras calientes y los movimientos lentos ofrecen una profunda relajación."],["Una pausa para los sentidos","Un masaje con aceite y movimientos fluidos para disfrutar de un momento de calma."],["Relajación centrada en los pies","Presiones suaves en los pies para una pausa relajante."],["Un momento de cuidado para las manos","Un tratamiento delicado de las manos en un ambiente sereno."],["Una consulta de bienestar integral","Orientación personalizada sobre los hábitos de bienestar cotidianos."]],"de":[["Ein wohltuendes Ritual für die Kopfhaut","Eine sanfte Behandlung für Kopfhaut und Haare zum Abschalten."],["Die Kunst der Entspannung","Sanfte, fließende Bewegungen helfen, alltägliche Anspannung loszulassen."],["Wohltuende Wärme","Warme Steine und langsame Bewegungen sorgen für tiefe Entspannung."],["Eine Auszeit für die Sinne","Eine sanfte Ölmassage für einen Moment der Ruhe."],["Entspannung für die Füße","Sanfter, gezielter Druck auf die Füße für eine erholsame Pause."],["Wohltuende Pflege für die Hände","Eine behutsame Behandlung der Hände in ruhiger Atmosphäre."],["Ganzheitliche Wohlfühlberatung","Individuelle Anregungen für das persönliche Wohlbefinden im Alltag."]],"it":[["Un rituale rilassante per il cuoio capelluto","Un trattamento delicato per cuoio capelluto e capelli, pensato per rilassarsi."],["L'arte del relax","Movimenti dolci e avvolgenti aiutano a sciogliere le tensioni quotidiane."],["Un calore avvolgente","Pietre calde e movimenti lenti regalano un profondo rilassamento."],["Una pausa per i sensi","Un massaggio con olio e movimenti fluidi per un momento di tranquillità."],["Relax dedicato ai piedi","Pressioni delicate sui piedi per una pausa rigenerante."],["Una coccola per le mani","Un trattamento delicato delle mani in un'atmosfera rilassante."],["Una consulenza di benessere olistico","Suggerimenti personalizzati sulle abitudini quotidiane di benessere."]],"nl":[["Een rustgevend ritueel voor de hoofdhuid","Een zachte behandeling voor hoofdhuid en haar om helemaal tot rust te komen."],["De kunst van ontspannen","Zachte, vloeiende bewegingen helpen dagelijkse spanning los te laten."],["Aangename warmte","Warme stenen en rustige bewegingen zorgen voor diepe ontspanning."],["Een moment voor de zintuigen","Een zachte oliemassage voor een heerlijk rustmoment."],["Ontspanning voor de voeten","Zachte drukpunten op de voeten voor een kalmerende pauze."],["Verzorging voor de handen","Een delicate handbehandeling in een rustige omgeving."],["Een holistisch welzijnsgesprek","Persoonlijke begeleiding rond dagelijkse gewoonten voor welzijn."]],"ru":[["Расслабляющий ритуал для кожи головы","Бережный уход за кожей головы и волосами помогает расслабиться."],["Искусство расслабления","Мягкие плавные движения помогают снять повседневное напряжение."],["Согревающее тепло","Тёплые камни и медленные движения дарят глубокое расслабление."],["Отдых для чувств","Нежный масляный массаж для спокойного отдыха."],["Расслабление для стоп","Мягкое воздействие на стопы для приятного отдыха."],["Забота о руках","Деликатная процедура для рук в спокойной обстановке."],["Комплексная консультация по благополучию","Индивидуальные рекомендации по привычкам для повседневного благополучия."]],"zh":[["舒缓头皮的护理仪式","轻柔护理头皮与头发，让身心慢慢放松。"],["放松的艺术","舒缓流畅的按摩手法，帮助释放日常压力。"],["温暖舒适的体验","温热的石头搭配缓慢的按摩动作，带来深度放松。"],["感官放松时光","轻柔的精油按摩，让您享受宁静的专属时刻。"],["专注足部的放松护理","通过轻柔的足部按压，享受舒适宁静的休息时光。"],["呵护双手的舒适时刻","在宁静的氛围中享受细致的手部护理。"],["整体健康生活咨询","围绕日常生活习惯，提供个性化的健康生活建议。"]],"ja":[["頭皮をいたわる癒やしのケア","頭皮と髪をやさしくケアし、心身をゆっくりほぐします。"],["くつろぎのひととき","なめらかでやさしい手技が、日々の緊張を和らげます。"],["心地よい温もり","温めた石とゆったりした手技で、深いリラクゼーションを。"],["五感を癒やす時間","オイルを使ったやさしいマッサージで、穏やかな時間をお過ごしください。"],["足元からのリラクゼーション","足へのやさしい刺激で、落ち着いたひとときを。"],["手をいたわるケア","静かな空間で、手を中心とした繊細なケアを行います。"],["心と体のための総合的な相談","毎日の生活習慣に関する、お一人おひとりに合わせたアドバイス。"]]};
const EXTRA_I18N={"fr":["✧ Massages bien-être","✧ Pont-l’Évêque · Normandie","LE COCON · HEAD SPA, MODELAGE ET MASSAGE À PONT-L’ÉVÊQUE","Agrandir la photo du salon","Photographie du salon Le Cocon","Photo du salon momentanément indisponible","Photographies du salon Le Cocon."],"en":["✧ Wellness massages","✧ Pont-l’Évêque · Normandy","LE COCON · HEAD SPA, WELLNESS TREATMENTS AND MASSAGES IN PONT-L’ÉVÊQUE","Enlarge salon photo","Photo of Le Cocon salon","Salon photo temporarily unavailable","Photos of Le Cocon salon."],"es":["✧ Masajes de bienestar","✧ Pont-l’Évêque · Normandía","LE COCON · HEAD SPA, TRATAMIENTOS Y MASAJES EN PONT-L’ÉVÊQUE","Ampliar foto del salón","Foto del salón Le Cocon","Foto temporalmente no disponible","Fotos del salón Le Cocon."],"de":["✧ Wellnessmassagen","✧ Pont-l’Évêque · Normandie","LE COCON · HEAD SPA, WOHLFÜHLBEHANDLUNGEN UND MASSAGEN IN PONT-L’ÉVÊQUE","Salonfoto vergrößern","Foto des Salons Le Cocon","Salonfoto vorübergehend nicht verfügbar","Fotos des Salons Le Cocon."],"it":["✧ Massaggi benessere","✧ Pont-l’Évêque · Normandia","LE COCON · HEAD SPA, TRATTAMENTI E MASSAGGI A PONT-L’ÉVÊQUE","Ingrandisci foto del salone","Foto del salone Le Cocon","Foto temporaneamente non disponibile","Foto del salone Le Cocon."],"nl":["✧ Wellnessmassages","✧ Pont-l’Évêque · Normandië","LE COCON · HEAD SPA, WELLNESSBEHANDELINGEN EN MASSAGES IN PONT-L’ÉVÊQUE","Salonfoto vergroten","Foto van salon Le Cocon","Salonfoto tijdelijk niet beschikbaar","Foto's van salon Le Cocon."],"ru":["✧ Расслабляющий массаж","✧ Пон-л’Эвек · Нормандия","LE COCON · HEAD SPA, УХОД И МАССАЖ В ПОН-Л’ЭВЕКЕ","Увеличить фото салона","Фото салона Le Cocon","Фото временно недоступно","Фотографии салона Le Cocon."],"zh":["✧ 放松按摩","✧ 蓬莱韦克 · 诺曼底","LE COCON · 蓬莱韦克的头皮水疗、护理与按摩","放大沙龙照片","Le Cocon 沙龙照片","照片暂时无法显示","Le Cocon 沙龙实景照片。"],"ja":["✧ リラクゼーションマッサージ","✧ ポン＝レヴェック · ノルマンディー","LE COCON · ポン＝レヴェックのヘッドスパ・ケア・マッサージ","サロンの写真を拡大","Le Coconのサロン写真","写真を一時的に表示できません","Le Coconのサロン写真。"]};
function serviceCopy(service,index){const row=SERVICE_I18N[lang]?.[index];return row?{subtitle:row[0],teaser:row[0],detail:row[1]}:service;}
const SALON_PHOTOS=[CUSTOM_MEDIA.vitrine,...Array.from({length:11},(_,i)=>'./'+String(i+2).padStart(2,'0')+'.jpg')];
function salonGallery(){
 const t=LANG[lang],e=EXTRA_I18N[lang]||EXTRA_I18N.fr;
 return `<section class="photo-section" id="galerie-salon"><div class="photo-heading"><h2>${t.gallery}</h2></div>
 <div class="salon-grid">${SALON_PHOTOS.map((url,i)=>`<button type="button" data-photo-url="${url}" aria-label="${e[3]} ${i+1}"><img src="assets/gallery-thumbnails/${i+1}.webp" loading="lazy" alt="${e[4]} ${i+1}" onerror="this.onerror=null;this.style.display='none';this.nextElementSibling.hidden=false"><span class="photo-fallback" hidden>${e[5]}</span></button>`).join('')}</div>
 <p class="photo-note">${e[6]}</p></section>`;
}
function place(){const t=LANG[lang];return `<section class="hero"><div class="copy"><span class="eyebrow">${t.place}</span><h1>${t.experience}</h1><p class="lead">${t.experienceBody}</p><div class="actions"><a class="btn btn-ghost" href="/galerie">${t.gallery}</a></div></div><div class="hero-img"><img src="${CUSTOM_MEDIA.lieu}" alt="Photo du lieu Le Cocon à Pont-l’Évêque"></div></section><section class="section"><div class="container"><div class="sectiontop"><span class="eyebrow">LE COCON</span><h2>${t.place}</h2><p>${t.experienceBody}</p></div><div class="actions"><a class="btn btn-ghost" href="/galerie">${t.gallery}</a></div></div></section>${cta()}`}
function galleryPage(){return `${salonGallery()}`}

const AUDIT_COPY={"fr":["Acheter une carte cadeau en ligne","Venir acheter une carte cadeau au salon","Sur Planity, choisissez « Offrir ». Pour venir au salon, réservez le créneau carte cadeau de 15 minutes.","Durées et disponibilités sur Planity.","Voir la fiche sur Google Maps"],"en":["Buy a gift card online","Buy a gift card at the salon","On Planity, choose “Offrir” to buy, or book the 15-minute gift card appointment.","Treatment durations and availability on Planity.","View on Google Maps"],"es":["Comprar una tarjeta regalo en línea","Comprar una tarjeta regalo en el salón","En Planity, selecciona « Offrir » para comprar o reserva la cita de 15 minutos para tarjetas regalo.","Duración y disponibilidad en Planity.","Ver en Google Maps"],"de":["Gutschein online kaufen","Gutschein im Salon kaufen","Wählen Sie auf Planity „Offrir“ oder buchen Sie den 15-minütigen Termin für Gutscheine.","Dauer und Verfügbarkeit auf Planity.","Auf Google Maps ansehen"],"it":["Acquista una carta regalo online","Acquista una carta regalo in salone","Su Planity scegli « Offrir » oppure prenota l’appuntamento di 15 minuti per le carte regalo.","Durata e disponibilità su Planity.","Vedi su Google Maps"],"nl":["Online een cadeaubon kopen","Een cadeaubon in de salon kopen","Kies op Planity ‘Offrir’ of boek de cadeaubonafspraak van 15 minuten.","Duur en beschikbaarheid op Planity.","Bekijk op Google Maps"],"ru":["Купить подарочную карту онлайн","Купить подарочную карту в салоне","На Planity выберите «Offrir» или запишитесь на 15-минутный визит за подарочной картой.","Длительность и свободные даты на Planity.","Открыть в Google Maps"],"zh":["在线购买礼品卡","到店购买礼品卡","在 Planity 选择「Offrir」购买，或预约 15 分钟的到店选购时段。","护理时长和可预约时段请见 Planity。","在 Google 地图上查看"],"ja":["ギフトカードをオンラインで購入","サロンでギフトカードを購入","Planityで「Offrir」を選ぶか、店頭で選ぶための15分枠をご予約ください。","所要時間と空き状況はPlanityでご確認ください。","Google マップで見る"]};
const GIFT_GUIDE={"fr":["1. Cliquez sur le bouton « ACHETER UNE CARTE CADEAU EN LIGNE » juste au-dessus.<br>2. Sur Planity, cliquez sur « Offrir ».<br>3. Choisissez une carte cadeau.<br>4. Suivez les indications à l’écran.","La première carte, « Montant variable », vous permet de choisir la somme à offrir. La personne pourra utiliser ce montant au salon pour une ou plusieurs prestations de son choix, selon le montant offert.","1. Cliquez sur le bouton « VENIR ACHETER UNE CARTE CADEAU AU SALON » juste au-dessus.<br>2. Sur Planity, choisissez « CARTE CADEAU À RETIRER AU SALON ».<br>3. Choisissez un jour et une heure. Réservez le créneau de 15 minutes.<br>4. Venez au salon choisir votre carte cadeau.<br>5. Vous paierez au salon, en espèces ou par carte bancaire.","Comme sur la photo, vous repartirez avec un petit sac cadeau contenant votre carte et quelques petites attentions, prêt à offrir.","Le paiement se fait en ligne. Après validation du paiement, la carte cadeau est envoyée automatiquement par e-mail. Si vous habitez loin, vous pouvez offrir un soin à un proche qui vit dans la région, sans avoir à vous déplacer."],"en":["1. Click the “BUY A GIFT CARD ONLINE” button just above.<br>2. On Planity, click “Offrir”.<br>3. Choose a gift card.<br>4. Follow the instructions on the screen.","The first card, “Montant variable”, lets you choose the amount. The recipient can spend it at the salon.","1. Click the “COME TO THE SALON TO BUY A GIFT CARD” button just above.<br>2. On Planity, choose “CARTE CADEAU À RETIRER AU SALON”.<br>3. Choose a day and time. Book the 15-minute appointment.<br>4. Come to the salon to choose your gift card.<br>5. Pay at the salon by cash or bank card.","As shown in the photo, you’ll leave with a small gift bag containing your card and a few little gifts, ready to give.","The whole purchase is completed online. After payment, the gift card is automatically sent by email. You can treat someone who lives nearby even if you live far away."],"es":["1. Pulsa el botón «COMPRAR UNA TARJETA REGALO EN LÍNEA» de arriba.<br>2. En Planity, pulsa «Offrir».<br>3. Elige una tarjeta regalo.<br>4. Sigue las indicaciones en pantalla.","La primera tarjeta, « Montant variable », permite elegir el importe. La persona que la reciba podrá utilizarlo en el salón.","1. Pulsa el botón «VENIR AL SALÓN A COMPRAR UNA TARJETA REGALO» de arriba.<br>2. En Planity, elige «CARTE CADEAU À RETIRER AU SALON».<br>3. Elige el día y la hora. Reserva la cita de 15 minutos.<br>4. Ven al salón para elegir la tarjeta.<br>5. Paga en el salón en efectivo o con tarjeta.","Como en la foto, se llevará una bolsita con su tarjeta y unos pequeños detalles, lista para regalar.","Todo se hace en línea. Tras el pago, la tarjeta regalo se envía automáticamente por correo electrónico. Puede regalar un tratamiento a alguien de la zona aunque viva lejos."],"de":["1. Klicken Sie oben auf „GUTSCHEIN ONLINE KAUFEN“.<br>2. Klicken Sie auf Planity auf „Offrir“.<br>3. Wählen Sie einen Gutschein.<br>4. Folgen Sie den Hinweisen auf dem Bildschirm.","Beim ersten Gutschein „Montant variable“ wählen Sie den Betrag selbst. Die beschenkte Person kann ihn im Salon einlösen.","1. Klicken Sie oben auf „GUTSCHEIN IM SALON KAUFEN“.<br>2. Wählen Sie auf Planity „CARTE CADEAU À RETIRER AU SALON“.<br>3. Wählen Sie einen Tag und eine Uhrzeit. Buchen Sie den 15-Minuten-Termin.<br>4. Kommen Sie in den Salon und wählen Sie Ihren Gutschein.<br>5. Sie bezahlen im Salon bar oder mit Karte.","Wie auf dem Foto erhalten Sie eine kleine Geschenktüte mit Ihrer Karte und ein paar kleinen Aufmerksamkeiten, fertig zum Verschenken.","Der Kauf läuft vollständig online ab. Nach der Zahlung wird der Gutschein automatisch per E-Mail verschickt. So können Sie auch aus der Ferne jemandem in der Region eine Behandlung schenken."],"it":["1. Clicca sul pulsante qui sopra «ACQUISTA UNA CARTA REGALO ONLINE».<br>2. Su Planity, clicca su «Offrir».<br>3. Scegli una carta regalo.<br>4. Segui le istruzioni sullo schermo.","Con la prima carta, « Montant variable », scegli l'importo da regalare. Chi la riceve potrà spenderlo in salone.","1. Clicca sul pulsante qui sopra «VIENI IN SALONE A COMPRARE UNA CARTA REGALO».<br>2. Su Planity, scegli «CARTE CADEAU À RETIRER AU SALON».<br>3. Scegli il giorno e l’ora. Prenota l’appuntamento di 15 minuti.<br>4. Vieni in salone e scegli la carta regalo.<br>5. Paga in salone in contanti o con carta.","Come nella foto, porterete via un sacchettino con la vostra carta regalo e qualche piccolo pensiero, pronto da regalare.","L’acquisto si svolge interamente online. Dopo il pagamento, la carta regalo viene inviata automaticamente via e-mail. Potete regalare un trattamento a chi vive in zona anche se abitate lontano."],"nl":["1. Klik hierboven op ‘KOOP ONLINE EEN CADEAUBON’.<br>2. Klik op Planity op ‘Offrir’.<br>3. Kies een cadeaubon.<br>4. Volg de aanwijzingen op het scherm.","Met de eerste bon, ‘Montant variable’, bepaal je zelf het bedrag. De ontvanger kan het in de salon besteden.","1. Klik hierboven op ‘KOM NAAR DE SALON OM EEN CADEAUBON TE KOPEN’.<br>2. Kies op Planity ‘CARTE CADEAU À RETIRER AU SALON’.<br>3. Kies een dag en tijd. Boek de afspraak van 15 minuten.<br>4. Kom naar de salon en kies je cadeaubon.<br>5. Betaal in de salon contant of met pinpas.","Zoals op de foto krijg je een cadeautasje met je cadeaubon en een paar kleine attenties mee, klaar om te geven.","U regelt de aankoop volledig online. Na betaling wordt de cadeaubon automatisch per e-mail verstuurd. Zo kunt u ook van ver weg iemand uit de regio een behandeling cadeau doen."],"ru":["1. Нажмите выше кнопку «КУПИТЬ ПОДАРОЧНУЮ КАРТУ ОНЛАЙН».<br>2. В Planity нажмите «Offrir».<br>3. Выберите подарочную карту.<br>4. Следуйте инструкциям на экране.","Первая карта, « Montant variable », позволяет выбрать сумму подарка. Получатель сможет потратить её в салоне.","1. Нажмите выше кнопку «КУПИТЬ ПОДАРОЧНУЮ КАРТУ В САЛОНЕ».<br>2. В Planity выберите «CARTE CADEAU À RETIRER AU SALON».<br>3. Выберите день и время. Запишитесь на 15 минут.<br>4. Приходите в салон и выберите подарочную карту.<br>5. Оплатите в салоне наличными или картой.","Как на фото, вы получите небольшой подарочный пакет с картой и приятными мелочами, готовый к вручению.","Весь процесс проходит онлайн. После оплаты подарочная карта автоматически отправляется по электронной почте. Даже если вы живёте далеко, вы можете подарить процедуру близкому человеку, который живёт в этом районе."],"zh":["1. 点击上方「在线购买礼品卡」按钮。<br>2. 在 Planity 点击「Offrir」。<br>3. 选择一张礼品卡。<br>4. 按照屏幕上的提示操作。","第一张「Montant variable」礼品卡可自选金额，收礼人可在沙龙使用这笔金额。","1. 点击上方「到店购买礼品卡」按钮。<br>2. 在 Planity 选择「CARTE CADEAU À RETIRER AU SALON」。<br>3. 选择日期和时间，预约 15 分钟。<br>4. 到店挑选礼品卡。<br>5. 在店内使用现金或银行卡付款。","如图所示，您将带走一个装有礼品卡和几份小礼物的手提袋，可以直接送给对方。","购买全程在线完成。付款后，礼品卡会自动通过电子邮件发送。即使您住得很远，也可以为住在当地的亲友送上一份护理礼物，无需到店。"],"ja":["1. 上の「ギフトカードをオンラインで購入」ボタンを押してください。<br>2. Planityで「Offrir」を押してください。<br>3. ギフトカードを選んでください。<br>4. 画面の案内に沿って進んでください。","最初の「Montant variable」は金額を自由に設定でき、受け取った方がサロンでその金額を利用できます。","1. 上の「サロンでギフトカードを購入」ボタンを押してください。<br>2. Planityで「CARTE CADEAU À RETIRER AU SALON」を選んでください。<br>3. 日時を選び、15分の予約をしてください。<br>4. サロンに来てギフトカードを選んでください。<br>5. お支払いはサロンで現金またはカードでお願いします。","写真のように、ギフトカードとちょっとした贈り物を入れた小さな手提げ袋を、そのまま贈れる形でお持ち帰りいただけます。","購入はすべてオンラインで完結し、お支払い後にギフトカードがメールで自動送信されます。遠方にお住まいでも、ご来店いただくことなく、近隣に住む大切な方に施術を贈れます。"]};
const GIFT_HELP_TOGGLE={"fr":["Voir les étapes pour acheter en ligne","Voir les étapes pour acheter au salon"],"en":["See the steps to buy online","See the steps to buy at the salon"],"es":["Ver los pasos para comprar en línea","Ver los pasos para comprar en el salón"],"de":["Schritte für den Online-Kauf ansehen","Schritte für den Kauf im Salon ansehen"],"it":["Vedi i passaggi per acquistare online","Vedi i passaggi per acquistare in salone"],"nl":["Bekijk de stappen voor online kopen","Bekijk de stappen voor kopen in de salon"],"ru":["Посмотреть шаги для покупки онлайн","Посмотреть шаги для покупки в салоне"],"zh":["查看在线购买步骤","查看到店购买步骤"],"ja":["オンライン購入の手順を見る","サロンで購入する手順を見る"]};
const GIFT_OPTION_INTRO={
fr:["Vous habitez loin, ne pouvez pas vous déplacer ou préférez tout faire en ligne ? Achetez votre carte cadeau depuis chez vous et recevez-la directement par e-mail.","Vous préférez venir au salon ? Choisissez votre carte avec moi. Nous pourrons en discuter et je vous expliquerai tout sur place."],
en:["Live far away, can’t travel, or prefer to do everything online? Buy your gift card from home and receive it by email.","Would you rather visit the salon? Choose your gift card with me. We can talk about what you’re looking for, and I’ll explain everything in person."],
es:["¿Vives lejos, no puedes desplazarte o prefieres hacerlo todo en línea? Compra tu tarjeta regalo desde casa y recíbela por correo electrónico.","¿Prefieres venir al salón? Elige tu tarjeta conmigo. Hablaremos de lo que buscas y te lo explicaré todo allí."],
de:["Wohnen Sie weit entfernt, können Sie nicht kommen oder möchten Sie alles online erledigen? Kaufen Sie Ihren Gutschein bequem von zu Hause aus und erhalten Sie ihn per E-Mail.","Möchten Sie lieber in den Salon kommen? Suchen Sie Ihre Karte mit mir aus. Wir besprechen Ihre Wünsche und ich erkläre Ihnen alles vor Ort."],
it:["Abiti lontano, non puoi spostarti o preferisci fare tutto online? Acquista la carta regalo da casa e ricevila via e-mail.","Preferisci venire in salone? Scegli la carta con me. Parleremo di ciò che desideri e ti spiegherò tutto di persona."],
nl:["Woon je ver weg, kun je niet langskomen of doe je alles liever online? Koop je cadeaubon vanuit huis en ontvang hem per e-mail.","Kom je liever naar de salon? Kies samen met mij een cadeaubon. We bespreken je wensen en ik leg alles ter plekke uit."],
ru:["Вы живёте далеко, не можете приехать или предпочитаете всё оформить онлайн? Купите подарочную карту, не выходя из дома, и получите её по электронной почте.","Предпочитаете прийти в салон? Выберите карту вместе со мной. Мы обсудим ваши пожелания, и я всё объясню на месте."],
zh:["如果您住得远、不方便出门，或更喜欢全程在线办理，可以在家购买礼品卡，并通过电子邮件收到。","如果您更想来沙龙，可以和我一起挑选礼品卡、聊聊您的想法，我会当面为您解释。"],
ja:["遠方にお住まいの方や、外出が難しい方、すべてオンラインで済ませたい方は、ご自宅からギフトカードをご購入いただき、メールで受け取れます。","サロンに来たい方は、私と一緒にカードを選び、ご希望を相談しながら、内容をその場でご説明します。"]
};
function gifts(){
 const t=LANG[lang],[buy,visit]=AUDIT_COPY[lang],[online,amount,inSalon,giftBag,emailDelivery]=GIFT_GUIDE[lang];
 const [onlineIntro,salonIntro]=GIFT_OPTION_INTRO[lang]||GIFT_OPTION_INTRO.fr;
 const [onlineHelpLabel,salonHelpLabel]=GIFT_HELP_TOGGLE[lang]||GIFT_HELP_TOGGLE.fr;
 const starGroup=(side,count)=>`<span class="christmas-stars christmas-stars-${side}" aria-hidden="true">${"<i></i>".repeat(count)}</span>`;
 const steps=(copy)=>{const lines=copy.split(/<br\s*\/?\s*>/i).filter(line=>/^\s*\d+\./.test(line));return `<div class="gift-help-steps">${lines.map((line,i)=>`<div class="gift-help-step"><span class="gift-help-number">${i+1}</span><span>${line.replace(/^\s*\d+\.\s*/,"")}</span></div>`).join("")}</div>`};
 const onlineScreen=`<div class="gift-help-planity" aria-label="Repère Planity du Cocon"><div class="gift-help-planity-head">${img('logo-le-cocon','')}<span>Le cocon – Head Spa – Modelage</span></div><div class="gift-help-planity-address">12 Rue Ménars · 14130 Pont-l’Évêque</div><div class="gift-help-planity-tabs"><span class="gift-help-planity-tab">Prendre RDV</span><span class="gift-help-planity-tab is-target">🎁 Offrir</span></div></div>`;
 const salonScreen=`<div class="gift-help-planity" aria-label="Repère Planity pour venir choisir une carte cadeau"><div class="gift-help-service"><span><strong>CARTE CADEAU À RETIRER AU SALON 🎁</strong><small>15 min · Petit créneau pour choisir sa carte</small></span><button type="button" tabindex="-1" aria-hidden="true">Choisir</button></div></div>`;
 return `<section class="hero"><div class="copy"><span class="eyebrow">${lang==='fr'?'Carte cadeau':t.gifts}</span><h1>${t.giftTitle}</h1><p class="lead">${t.giftBody}</p><p>${MASSAGE_PRIVACY[lang]}</p><div class="gift-options"><section class="gift-option"><a class="btn christmas-gift-cta gift-option-cta" href="${PLANITY}" target="_blank" rel="noopener">${starGroup("left",4)}<span class="gift-option-label">${buy}</span>${starGroup("right",5)}</a><p class="gift-option-intro">${onlineIntro}</p><details class="gift-help"><summary><span class="gift-help-toggle" aria-hidden="true">+</span>${onlineHelpLabel}</summary><div class="gift-help-panel">${onlineScreen}${steps(online)}<div class="gift-help-note">${amount}</div><div class="gift-help-note">${emailDelivery}</div></div></details></section><section class="gift-option"><a class="btn btn-ghost christmas-gift-cta gift-option-cta" href="${PLANITY}" target="_blank" rel="noopener">${starGroup("left",4)}<span class="gift-option-label">${visit}</span>${starGroup("right",5)}</a><p class="gift-option-intro">${salonIntro}</p><details class="gift-help"><summary><span class="gift-help-toggle" aria-hidden="true">+</span>${salonHelpLabel}</summary><div class="gift-help-panel">${salonScreen}${steps(inSalon)}<div class="gift-help-photo"><img src="${CUSTOM_MEDIA.cadeau}" alt="Carte cadeau du Cocon"><p>${giftBag}</p></div></div></details></section></div></div><div class="hero-img"><img src="${CUSTOM_MEDIA.cadeau}" alt="Carte cadeau du salon Le Cocon"></div></section>${duoFeature(true)}${cta('gift-page-cta')}`;
}
const SOCIAL_TITLES={"fr":"Retrouvez-nous sur les réseaux sociaux","en":"Follow us on social media","es":"Síguenos en redes sociales","de":"Folgen Sie uns in den sozialen Medien","it":"Seguici sui social","nl":"Volg ons op sociale media","ru":"Мы в социальных сетях","zh":"关注我们的社交媒体","ja":"SNSでフォローしてください"};
function socialLinks(){return `<section class="cocon-social"><h2>${SOCIAL_TITLES[lang]||SOCIAL_TITLES.fr}</h2><div class="cocon-social-links"><a class="cocon-social-link" href="https://www.instagram.com/lecocon.bienetre?evlk=MTRxYTVhbnV3eW9n" target="_blank" rel="noopener noreferrer"><svg aria-hidden="true" viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="2" width="20" height="20" rx="6"/><circle cx="12" cy="12" r="4.5"/><circle cx="18" cy="6" r="1" fill="currentColor" stroke="none"/></svg><span>Instagram</span></a><a class="cocon-social-link" href="https://www.facebook.com/share/151LH5nFePx/" target="_blank" rel="noopener noreferrer"><svg aria-hidden="true" viewBox="0 0 24 24" width="24" height="24" fill="currentColor"><path d="M24 12a12 12 0 1 0-13.875 11.854v-8.385H7.078V12h3.047V9.356c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.234 2.686.234v2.953H15.83c-1.49 0-1.955.925-1.955 1.874V12h3.328l-.532 3.469h-2.796v8.385A12 12 0 0 0 24 12z"/></svg><span>Facebook</span></a><a class="cocon-social-link" href="https://www.tiktok.com/@lecocon_pearlbartert?_r=1&amp;_t=ZN-9Bl0ms1k0LW" target="_blank" rel="noopener noreferrer"><svg aria-hidden="true" viewBox="0 0 24 24" width="24" height="24" fill="currentColor"><path d="M16.6 0c.3 2.6 1.8 4.2 4.4 4.4v3.7a8.4 8.4 0 0 1-4.4-1.4v8.1a7.2 7.2 0 1 1-6.3-7.1v3.8a3.5 3.5 0 1 0 2.5 3.3V0z"/></svg><span>TikTok</span></a></div></section>`}
const CONTACT_GROUPS={"fr":["Nous contacter","Venir au Cocon","Ajouter à mes contacts"],"en":["Contact us","Visit Le Cocon","Save contact"],"es":["Contáctenos","Visitar Le Cocon","Guardar contacto"],"de":["Kontakt","Ihr Besuch im Le Cocon","Kontakt speichern"],"it":["Contattaci","Visita Le Cocon","Salva contatto"],"nl":["Neem contact op","Bezoek Le Cocon","Contact opslaan"],"ru":["Связаться с нами","Как добраться до Le Cocon","Сохранить контакт"],"zh":["联系我们","前往 Le Cocon","保存联系人"],"ja":["お問い合わせ","Le Cocon へのアクセス","連絡先を保存"]};
function contact(){const t=LANG[lang],c=CONTACT_GROUPS[lang]||CONTACT_GROUPS.fr;return `<section class="section contact-access"><div class="container"><div class="sectiontop"><span class="eyebrow">LE COCON · PONT-L’ÉVÊQUE</span><h1>${t.contact}</h1><p>${t.contactBody}</p></div><div class="contact-unified"><section class="contact-column"><h2>${c[0]}</h2><div class="contact-details"><div><span class="eyebrow">${t.telephoneLabel}</span><p class="contact-phone"><a href="tel:+33259163936">02 59 16 39 36</a></p><a class="contact-international" href="tel:+33259163936">+33 2 59 16 39 36</a></div><div><span class="eyebrow">${t.emailLabel}</span><p><a href="mailto:salon@lecocon14.com">salon@lecocon14.com</a></p></div></div><div class="contact-actions"><a class="contact-gold-link" href="/le-cocon-contact.vcf" download="Le-Cocon.vcf">＋ ${c[2]}</a><a class="contact-gold-link" href="mailto:salon@lecocon14.com">${t.emailAction}</a></div>${socialLinks()}</section><section class="contact-column contact-visit"><h2>${c[1]}</h2><span class="eyebrow">${t.addressLabel}</span><p class="contact-address">Le Cocon<br>12 rue Ménars<br>14130 Pont-l’Évêque</p><div class="contact-actions"><a class="btn" href="https://www.google.com/maps/search/?api=1&amp;query=12%20rue%20M%C3%A9nars%2C%2014130%20Pont-l%27%C3%89v%C3%AAque" target="_blank" rel="noopener">${t.mapDirections}</a></div><div class="contact-directory"><a class="pagesjaunes-link" href="https://www.pagesjaunes.fr/pros/65582970" target="_blank" rel="noopener noreferrer"><img class="pagesjaunes-logo" src="https://www.google.com/s2/favicons?domain=pagesjaunes.fr&amp;sz=64" alt="" width="27" height="27" loading="lazy"><span>${t.pagesJaunesLabel}</span></a></div></section></div><div class="contact-map"><div class="map-wrap"><iframe title="Google Maps · Le Cocon, 12 rue Ménars, Pont-l’Évêque" data-consent-map="https://www.google.com/maps?q=12%20rue%20M%C3%A9nars%2C%2014130%20Pont-l%27%C3%89v%C3%AAque&amp;output=embed" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe></div></div>${lang==='fr'?'<p class="contact-local">Le salon vous accueille au cœur du Pays d’Auge, à proximité de Deauville, Trouville-sur-Mer, Honfleur, Lisieux, Beuzeville, Cabourg et Ouistreham.</p>':''}${reviews()}</div></section>${cta()}`}
const LEGAL_PAGES={"mentions-legales": {"title": "Mentions légales", "intro": "Informations sur l’éditeur et le fonctionnement du site.", "sections": [["Éditeur du site", "<p><strong>Nom commercial :</strong> Le Cocon Bien-Être</p><p><strong>Exploitante :</strong> Pearl Bartert</p><p><strong>Statut :</strong> Entreprise individuelle</p><p><strong>SIRET :</strong> 941 889 388 00018</p><p><strong>Adresse :</strong> 12 rue Ménars, 14130 Pont-l’Évêque</p><p><strong>Téléphone :</strong> <a href='tel:+33259163936'>📞 02 59 16 39 36</a><br><a href='tel:+33259163936'>🌐 +33 2 59 16 39 36</a></p><p><strong>E-mail :</strong> <a href='mailto:salon@lecocon14.com'>salon@lecocon14.com</a></p>"], ["Direction de la publication", "<p>Pearl Bartert.</p>"], ["Hébergement", "<p>La version actuelle du site utilise un dépôt GitHub et peut être publiée sur Cloudflare Pages. L’hébergeur effectif et ses coordonnées doivent être vérifiés avant mise en ligne de cette nouvelle version.</p>"], ["Propriété intellectuelle", "<p>Les contenus, visuels, photographies, textes et éléments graphiques ne peuvent pas être reproduits ou réutilisés sans autorisation préalable, sous réserve des exceptions prévues par la loi.</p>"], ["Contact", "<p>Pour toute question relative au site : <a href='mailto:salon@lecocon14.com'>salon@lecocon14.com</a>.</p>"]]}, "politique-confidentialite": {"title": "Politique de confidentialité", "intro": "Nos informations sur la protection des données personnelles.", "sections": [["Responsable du traitement", "<p>Le Cocon Bien-Être, représenté par son exploitante, 12 rue Ménars, 14130 Pont-l’Évêque.</p><p>Contact : <a href='mailto:salon@lecocon14.com'>salon@lecocon14.com</a>.</p>"], ["Données personnelles", "<p>Ce site vitrine propose des liens vers des services externes, notamment Planity. Les données que vous transmettez à ces services relèvent de leurs politiques de confidentialité. Si vous contactez le salon par e-mail, vos informations servent à répondre à votre demande.</p>"], ["Utilisation et conservation", "<p>Les informations communiquées au salon sont utilisées pour répondre aux demandes et assurer les services concernés, puis conservées pendant la durée nécessaire aux finalités poursuivies et obligations légales applicables.</p>"], ["Vos droits", "<p>Vous pouvez, dans les conditions prévues par le RGPD, demander l’accès, la rectification, l’effacement, la limitation ou la portabilité de vos données, et vous opposer à certains traitements.</p><p>Pour exercer vos droits : <a href='mailto:salon@lecocon14.com'>salon@lecocon14.com</a>. Vous pouvez également saisir la CNIL.</p>"], ["Traceurs et stockage local", "<p>Cette démo utilise le stockage local du navigateur pour retenir votre langue préférée. Les traceurs du site publié doivent être vérifiés avant la mise en ligne de toute nouvelle version.</p>"]]}, "cookies": {"title": "Cookies et autres traceurs", "intro": "Des informations simples sur les technologies utilisées pendant la navigation.", "sections": [["Qu’est-ce qu’un cookie ?", "<p>Un cookie est un petit fichier ou un traceur susceptible d’être enregistré sur votre appareil lors de votre visite sur un site.</p>"], ["Stockage de la langue", "<p>Ce site enregistre votre choix de langue dans le stockage local de votre navigateur afin de le conserver lors de la navigation. Cette préférence ne sert pas au ciblage publicitaire.</p>"], ["Services externes", "<p>Les liens vers Planity et Google Maps ouvrent ces services lorsque vous cliquez dessus. La page Contact et accès intègre une carte Google Maps qui se charge à l’approche de la zone d’affichage. Google peut alors recevoir des informations techniques liées à votre navigation. Les politiques de confidentialité de ces services s’appliquent lorsque vous les consultez.</p>"], ["Gérer vos choix", "<p>Vous pouvez supprimer les données de navigation enregistrées dans votre navigateur. Si des traceurs nécessitant un consentement sont ajoutés au site publié, leur activation devra respecter les choix des visiteurs.</p>"], ["Contact", "<p>Pour toute question : <a href='mailto:salon@lecocon14.com'>salon@lecocon14.com</a>.</p>"]]}};
