const LEGAL_CONTACT_EMAIL="<a href='mailto:salon@lecocon14.com'>salon@lecocon14.com</a>";
function localizedLegal(which){
 const t=LEGAL_TRANSLATIONS[lang];if(!t)return LEGAL_PAGES[which]||LEGAL_PAGES['mentions-legales'];
 const label=(a,b)=>'<p><strong>'+a+':</strong> '+b+'</p>';
 const contact=t.questions+' '+LEGAL_CONTACT_EMAIL;
 const titles=which==='mentions-legales'?t.legalSections:which==='politique-confidentialite'?t.privacySections:t.cookieSections;
 let sections;
 if(which==='mentions-legales'){
  sections=[
   label(t.owner[0],'Le Cocon Bien-Être')+label(t.owner[1],'Pearl Bartert')+label(t.owner[2],t.self)+label('SIRET','941 889 388 00018')+label(t.owner[3],'12 rue Ménars, 14130 Pont-l’Évêque')+label(t.owner[4],"<a href='tel:+33259163936'>📞 02 59 16 39 36</a><br><a href='tel:+33259163936'>🌐 +33 2 59 16 39 36</a>")+label(t.owner[5],LEGAL_CONTACT_EMAIL),
   '<p>Pearl Bartert.</p>','<p>'+t.host+'</p>','<p>'+t.ip+'</p>','<p>'+t.ask+' '+LEGAL_CONTACT_EMAIL+'</p>'
  ];
 }else if(which==='politique-confidentialite'){
  sections=['<p>'+t.controller+'</p><p>'+contact+'</p>','<p>'+t.data+'</p>','<p>'+t.retention+'</p>','<p>'+t.rights+'</p><p>'+t.exercise+' '+LEGAL_CONTACT_EMAIL+'. '+t.authority+'</p>','<p>'+CONSENT_POLICY[lang]+'</p>'];
 }else{
  sections=['<p>'+t.what+'</p>','<p>'+t.preference+'</p>','<p>'+t.external+'</p>','<p>'+CONSENT_POLICY[lang]+'</p>','<p>'+contact+'</p>'];
 }
 return {title:which==='mentions-legales'?t.legal:which==='politique-confidentialite'?t.privacy:t.cookies,intro:which==='mentions-legales'?t.legalIntro:which==='politique-confidentialite'?t.privacyIntro:t.cookiesIntro,sections:titles.map((title,i)=>[title,sections[i]])};
}
const CONSENT_POLICY={"fr":"Le site conserve votre langue et votre choix de consentement dans le stockage local du navigateur (choix conservé 180 jours). Google Analytics 4, fourni par Google, est activé uniquement avec votre accord pour mesurer les visites, les pages consultées et les clics vers le téléphone, l’e-mail, Planity, les cartes cadeaux et les massages en entreprise. Il peut utiliser les cookies _ga et _ga_* (durée maximale configurée : 180 jours, sans renouvellement automatique). Les fonctionnalités publicitaires de Google Analytics sont désactivées dans le code du site. Google Maps est chargé uniquement avec votre accord distinct. Vous pouvez tout refuser, accepter ou personnaliser vos choix, puis les modifier ou retirer votre consentement via « Gérer mes cookies » en bas de chaque page. Vous pouvez également supprimer les cookies dans votre navigateur. Google peut traiter des données hors de l’Espace économique européen. Consultez <a href='https://policies.google.com/privacy' target='_blank' rel='noopener'>la politique de confidentialité de Google</a>. Les liens externes, notamment Planity, relèvent des politiques propres à ces services.","en":"Language and consent choices are stored locally. Consent is retained for six months. Google Maps is blocked without consent. Google Analytics 4 measures visits and service link clicks only with consent. You can refuse or withdraw consent at any time using Manage cookies in the footer. Google may process data outside the EEA. See https://policies.google.com/privacy.","es":"El idioma y el consentimiento se guardan localmente durante seis meses para el consentimiento. Google Maps requiere autorización. Google Analytics 4, mide visitas y clics solo con permiso. Puede retirar el consentimiento en Gestionar cookies. Google puede tratar datos fuera del EEE. https://policies.google.com/privacy","de":"Sprache und Einwilligung werden lokal gespeichert; die Einwilligung gilt sechs Monate. Google Maps wird erst nach Zustimmung geladen. Google Analytics 4 misst Besuche und Klicks nur mit Zustimmung. Widerruf jederzeit über Cookies verwalten. Google kann Daten außerhalb des EWR verarbeiten. https://policies.google.com/privacy","it":"Lingua e consenso sono salvati localmente; il consenso dura sei mesi. Google Maps richiede il consenso. Google Analytics 4, misura visite e clic solo con consenso. Revoca in qualsiasi momento tramite Gestisci cookie. Google può trattare dati fuori dal SEE. https://policies.google.com/privacy","nl":"Taal en toestemming worden lokaal opgeslagen; toestemming geldt zes maanden. Google Maps vereist toestemming.  Google Analytics 4 meet bezoeken en klikken alleen met toestemming. Intrekken kan via Cookies beheren. Google kan gegevens buiten de EER verwerken. https://policies.google.com/privacy","ru":"Язык и согласие сохраняются локально; согласие действует шесть месяцев. Google Maps загружается только с согласия. Google Analytics 4 измеряет посещения и клики только с согласия. Отозвать согласие можно в разделе управления cookies. Google может обрабатывать данные за пределами ЕЭЗ. https://policies.google.com/privacy","zh":"语言和同意选项保存在本地，同意有效期为六个月。Google 地图仅在同意后加载。Google Analytics 4仅在同意时统计访问和点击。您可随时通过页脚的管理 Cookie 撤回同意。Google 可能在欧洲经济区之外处理数据。https://policies.google.com/privacy","ja":"言語と同意の選択は端末に保存され、同意の保存期間は6か月です。Google マップは同意後のみ読み込まれます。Google Analytics 4 は同意がある場合のみアクセスとクリックを計測します。フッターの Cookie の管理からいつでも撤回できます。Google は EEA 域外でデータを処理する場合があります。https://policies.google.com/privacy"};
function legal(which){
 const p=localizedLegal(which),t=LEGAL_TRANSLATIONS[lang];
 return `<section class="legal-page"><div class="legal-wrap"><a class="legal-back" href="/#/">← ${t?t.back:"Retour à l’accueil"}</a><span class="eyebrow">LE COCON · ${t?t.info:"INFORMATIONS"}</span><h1>${p.title}</h1><p class="legal-intro">${p.intro}</p>${p.sections.map(([title,body])=>`<section class="legal-panel"><h2>${title}</h2>${body}</section>`).join('')}<div class="mini-links"><a href="/#/mentions-legales">${t?t.legal:"Mentions légales"}</a><a href="/#/politique-confidentialite">${t?t.privacy:"Confidentialité"}</a><a href="/#/cookies">${t?t.cookies:"Cookies"}</a></div></div></section>`;
}
function render(){if(/^#\/?contact\/?$/.test(location.hash))history.replaceState(history.state,'',location.pathname+location.search+'#/contact-et-acces');if(/^#\/?experience\/?$/.test(location.hash))history.replaceState(history.state,'',location.pathname+location.search+'#/le-lieu');if(/^#\/?bons-cadeaux\/?$/.test(location.hash))history.replaceState(history.state,'',location.pathname+location.search+'#/cartes-cadeaux');nav();const route=decodeURIComponent(location.hash.replace(/^#\/?/,'')),id=location.hash?route.replace(/^\//,''):(document.body.dataset.appRoute||'');let html= id===''?home():id==='soins'?list():id==='le-lieu'?place():id==='galerie'?galleryPage():id==='cartes-cadeaux'?gifts():id==='bien-etre-a-deux'?duoPage():id==='entreprises'?companyPage():id==='contact-et-acces'?contact():['mentions-legales','politique-confidentialite','cookies'].includes(id)?legal(id):SERVICES.find(s=>s.id===id)?details(SERVICES.find(s=>s.id===id)):home();document.getElementById('app').innerHTML=html;document.getElementById('links').classList.remove('open');document.getElementById('hamb').setAttribute('aria-expanded','false');document.querySelectorAll('#links a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===link(id)));window.scrollTo(0,0);}
document.getElementById('brand-logo').src=HEADER_ORIGINAL_LOTUS;document.getElementById('language').value=lang;document.getElementById('language').addEventListener('change',e=>{lang=e.target.value;try{localStorage.setItem('lecocon-lang',lang)}catch(e){}render()});document.getElementById('hamb').addEventListener('click',()=>{let links=document.getElementById('links'),on=links.classList.toggle('open');document.getElementById('hamb').setAttribute('aria-expanded',String(on))});window.addEventListener('hashchange',render);
const lightbox=document.getElementById('lightbox');
const bigImage=document.getElementById('big-image');
const closePhoto=document.getElementById('close-lightbox');
const previousPhoto=document.getElementById('previous-photo');
const nextPhoto=document.getElementById('next-photo');
const photoSelector='[data-photo],[data-photo-url]';
const photoLabels={
 fr:['Photo précédente','Photo suivante','Fermer la photo'],
 en:['Previous photo','Next photo','Close photo'],
 es:['Foto anterior','Foto siguiente','Cerrar foto'],
 de:['Vorheriges Foto','Nächstes Foto','Foto schließen'],
 it:['Foto precedente','Foto successiva','Chiudi foto'],
 nl:['Vorige foto','Volgende foto','Foto sluiten'],
 ru:['Предыдущее фото','Следующее фото','Закрыть фото'],
 zh:['上一张照片','下一张照片','关闭照片'],
 ja:['前の写真','次の写真','写真を閉じる']
};
let photos=[],photoIndex=0,photoOpener=null,touchStart=null;
function showPhoto(){
 const photo=photos[photoIndex];
 bigImage.alt=photo.querySelector('img')?.alt||'';
 bigImage.src=photo.dataset.photoUrl||ASSETS[photo.dataset.photo];
}
function stepPhoto(direction){
 if(photos.length<2)return;
 photoIndex=(photoIndex+direction+photos.length)%photos.length;
 showPhoto();
}
function closeBox(){
 if(!lightbox.classList.contains('open'))return;
 lightbox.classList.remove('open');
 lightbox.setAttribute('aria-hidden','true');
 bigImage.style.display='none';
 touchStart=null;
 photoOpener?.focus({preventScroll:true});
}
document.addEventListener('click',event=>{
 const photo=event.target.closest(photoSelector);
 if(!photo)return;
 photoOpener=photo;
 const gallery=photo.closest('.salon-grid,.gallery');
 photos=gallery?[...gallery.querySelectorAll(photoSelector)]:[photo];
 photoIndex=photos.indexOf(photo);
 const labels=photoLabels[lang]||photoLabels.fr;
 [previousPhoto,nextPhoto,closePhoto].forEach((button,index)=>button.setAttribute('aria-label',labels[index]));
 lightbox.setAttribute('aria-label',LANG[lang].gallery);
 previousPhoto.hidden=nextPhoto.hidden=photos.length<2;
 showPhoto();
 bigImage.style.display='block';
 lightbox.classList.add('open');
 lightbox.setAttribute('aria-hidden','false');
 closePhoto.focus({preventScroll:true});
});
previousPhoto.addEventListener('click',()=>stepPhoto(-1));
nextPhoto.addEventListener('click',()=>stepPhoto(1));
closePhoto.addEventListener('click',closeBox);
lightbox.addEventListener('click',event=>{
 if(event.target===lightbox)closeBox();
});
window.addEventListener('hashchange',closeBox);
document.addEventListener('keydown',event=>{
 if(!lightbox.classList.contains('open'))return;
 if(event.key==='Escape')closeBox();
 if(event.key==='ArrowLeft'||event.key==='ArrowRight'){
  event.preventDefault();
  stepPhoto(event.key==='ArrowLeft'?-1:1);
 }
 if(event.key==='Tab'){
  const buttons=[closePhoto,previousPhoto,nextPhoto].filter(button=>!button.hidden);
  const index=buttons.indexOf(document.activeElement);
  event.preventDefault();
  buttons[(index+(event.shiftKey?-1:1)+buttons.length)%buttons.length].focus();
 }
});
bigImage.addEventListener('touchstart',event=>{
 const touch=event.touches[0];
 touchStart=event.touches.length===1?{x:touch.clientX,y:touch.clientY}:null;
},{passive:true});
bigImage.addEventListener('touchcancel',()=>{touchStart=null});
bigImage.addEventListener('touchend',event=>{
 if(!touchStart)return;
 const touch=event.changedTouches[0];
 const dx=touch.clientX-touchStart.x;
 const dy=touch.clientY-touchStart.y;
 touchStart=null;
 if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.4)stepPhoto(dx<0?1:-1);
},{passive:true});
render();
